78	function scheduleSnapshot(snapshot: CardSequenceDraftSnapshot): ActionScheduleSnapshot {
79	    const common = { message: null, open: snapshot.open }
80	    if (snapshot.triggerType === 'at') {
81	        return { ...common, timestamp: snapshot.timestamp, triggerType: 'at' }
