83	    if (snapshot.triggerType === 'account-reset') {
84	        return {
85	            ...common,
86	            agent: snapshot.agent,
87	            limitId: snapshot.limitId,
88	            triggerType: 'account-reset',
89	            windowId: snapshot.windowId,
90	        }
91	    }
92	    if (snapshot.triggerType === 'card-state') {
93	        return {
94	            ...common,
95	            cardInternalId: snapshot.cardInternalId,
96	            targetState: snapshot.targetState,
97	            triggerType: 'card-state',
98	        }
99	    }
100	
101	    throw new Error('Now trigger has no action schedule snapshot')
102	}
