110	function validationMessage(snapshot: CardSequenceDraftSnapshot, sources: CardSequenceValidationSources): string | null {
111	    if (snapshot.cardInternalIds.length === 0) return 'Add at least one card'
112	    const cards = dataService.getState().snapshot?.activeCards ?? [];
113	    if (cards.some((card) => snapshot.cardInternalIds.includes(card.header.internalId!) && isSequenceCardAssigned(card))) return 'Sequence cards cannot have a worktree assignment';
114	    if (!sources.cardsAvailable) return 'Every sequence card must remain active'
115	    if (!snapshot.actionId || !sources.actionIds.includes(snapshot.actionId)) return 'Select an action available for every card'
116	    if (!snapshot.readyState || !sources.readyStates.includes(snapshot.readyState)) return 'Select a configured ready state'
117	    if (snapshot.triggerType === 'card-state' && snapshot.cardInternalIds.includes(snapshot.cardInternalId)) {
118	        return 'Trigger card cannot be part of the sequence'
119	    }
120	    try {
121	        selectedTrigger(snapshot, sources)
122	    } catch (error) {
123	        return error instanceof Error ? error.message : 'Complete the selected trigger'
124	    }
125	
126	    return null
127	}
